\begin{equation}
\label{eq:work}
 X_\pm=k\Im\langle f_\pm,p_\pm\rangle_{D_R},\qquad
 A_\pm=k\int_{D_R} E_\pm^\dagger\operatorname{Im}_{\!H}\chi E_\pm\,\mathrm{d}\mathbf x.
\end{equation}

\begin{equation}
\label{eq:farfield}
 F_p(\mathbf n)=\frac{k^2}{4\pi}\Pi_{\mathbf n}
 \int_{D_R}p(\mathbf x)e^{-ik\mathbf n\cdot\mathbf x}\,\mathrm{d}\mathbf x,
 \quad\Pi_{\mathbf n}=I-\mathbf n\mathbf n^T,\qquad
 S=\int_{S^2}\lVert F_p(\mathbf n)\rVert^2\,\mathrm{d}\Omega.
\end{equation}

\begin{equation}
\label{eq:balance}
 X_+=X_-=X,\qquad X=A_\pm+S_\pm,\qquad
 X_\pm=\frac{4\pi}{k}\Im\{\mathbf e_y^\dagger F_{p_\pm}(\pm\mathbf e_z)\}.
\end{equation}

\begin{equation}
\label{eq:radiation}
 \Im\langle p,K_Dp\rangle
 =\frac{k^3}{16\pi^2}\int_{S^2}
 \left\lVert\Pi_{\mathbf n}\int_Dp(\mathbf x)e^{-ik\mathbf n\cdot\mathbf x}\,\mathrm{d}\mathbf x\right\rVert^2\,\mathrm{d}\Omega
